#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int dp[100001];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = 1000000;
        int x = i;

        while (x > 0) {
            int d = x % 10;
            x /= 10;

            if (d > 0 && dp[i - d] + 1 < dp[i]) {
                dp[i] = dp[i - d] + 1;
            }
        }
    }

    printf("%d\n", dp[n]);
    return 0;
}
